import React, { useState, useContext, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Eye, EyeOff } from 'lucide-react';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';

const TAGLINES = [
  {
    title: "Reprends là où tu t'es arrêté.",
    text: "Accède à tes formations, suis ta progression, et continue à monter en compétence sur des scénarios réels de cyberdéfense.",
  },
  {
    title: "Chaque connexion te rapproche du terrain.",
    text: "Retrouve tes modules, tes exercices et ta progression, exactement là où tu les as laissés.",
  },
  {
    title: "La cybersécurité s'apprend en pratiquant.",
    text: "Reconnecte-toi pour continuer tes scénarios d'attaque et de défense, avec des cas concrets et réalistes.",
  },
  {
    title: "Ton parcours t'attend.",
    text: "Reviens là où tu en étais, et poursuis ta montée en compétence sur le réseau, le pentest et la cyberdéfense.",
  },
  {
    title: "Prêt pour la suite ?",
    text: "Tes formations, ta progression et tes ressources t'attendent, à l'endroit exact où tu les as quittées.",
  },
];

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const tagline = useMemo(() => TAGLINES[Math.floor(Math.random() * TAGLINES.length)], []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const body = new URLSearchParams();
      body.append('username', email);
      body.append('password', password);
      const res = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body,
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.detail || 'Email ou mot de passe incorrect.');
      }
      const data = await res.json();
      login(data.access_token, data.user);
      navigate('/dashboard');
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">
      <div className="hidden lg:flex lg:w-1/2 relative overflow-hidden border-r border-slate-800/60 items-center justify-center p-16">
        <div className="absolute top-1/3 left-1/4 w-[400px] h-[400px] bg-blue-600/20 blur-[120px] rounded-full"></div>
        <div className="relative max-w-md">
          <div className="flex items-center gap-2.5 mb-10">
            <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-xl shadow-lg shadow-blue-500/20">A</div>
            <span className="text-xl font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
          </div>
          <h1 className="text-3xl font-bold text-white mb-4 leading-snug">{tagline.title}</h1>
          <p className="text-slate-400 text-sm leading-relaxed">{tagline.text}</p>
        </div>
      </div>

      <div className="w-full lg:w-1/2 flex items-center justify-center p-6 sm:p-12">
        <div className="w-full max-w-sm">
          <div className="flex lg:hidden items-center gap-2.5 justify-center mb-10">
            <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-lg">A</div>
            <span className="text-lg font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
          </div>

          <h2 className="text-2xl font-bold text-white mb-1">Connexion</h2>
          <p className="text-slate-500 text-sm mb-8">Content de te revoir.</p>

          {error && <div className="bg-red-500/10 border border-red-500/30 text-red-400 text-sm rounded-lg px-4 py-3 mb-4">{error}</div>}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-xs font-semibold text-slate-400 mb-1.5 block">Email</label>
              <input type="email" placeholder="toi@exemple.com" required onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-900/60 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-400 mb-1.5 block">Mot de passe</label>
              <div className="relative">
                <input type={showPassword ? 'text' : 'password'} placeholder="••••••••" required onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-900/60 border border-slate-800 text-white px-4 py-3 pr-11 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300">
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>
            <div className="text-right">
              <Link to="/forgot-password" className="text-xs text-blue-400 hover:text-blue-300">Mot de passe oublié ?</Link>
            </div>
            <button type="submit" disabled={loading} className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 text-white font-semibold py-3 rounded-lg text-sm transition-colors mt-2">
              {loading ? 'Connexion...' : 'Se connecter'}
            </button>
          </form>

          <p className="text-center text-slate-500 text-sm mt-8">
            Pas encore de compte ? <Link to="/register" className="text-blue-400 hover:text-blue-300 font-semibold">S'inscrire</Link>
          </p>
        </div>
      </div>
    </div>
  );
};
export default Login;
